package android.view; import android.graphics.Rect; public class View { public interface OnAttachStateChangeListener {void onViewAttachedToWindow(View v);void onViewDetachedFromWindow(View v);} public boolean shown=true,attached=true,focused=true; public int x,y; public Rect bounds=new Rect(0,0,400,400); public View root=this; public Object params=new Object();public WindowInsets insets=new WindowInsets(); public boolean isShown(){return shown;}public boolean isAttachedToWindow(){return attached;}public boolean hasWindowFocus(){return focused;} public View getRootView(){return root;}public Object getLayoutParams(){return params;}public void getLocationOnScreen(int[] a){a[0]=x;a[1]=y;}public boolean getGlobalVisibleRect(Rect r){r.set(bounds.left,bounds.top,bounds.right,bounds.bottom);return shown;}public void addOnAttachStateChangeListener(OnAttachStateChangeListener l){}public boolean post(Runnable r){r.run();return true;}public WindowInsets getRootWindowInsets(){return insets;} }
